re transactioncode = \'04-1-12-069-000728-00001\'~~>UPDATE tb_bill as x left join(select b.billcode,if((b.finalbillcharge-if(isnull(p.amountpaid),0,p.amountpaid))>0,0,1) as paid from (select billcode,((billcharge + GETPENALTY(billcharge, duegraceperiod,  dueexempt,  arrears,  penaltyamount,  paid))+adjustdebit)-adjustcredit as finalbillcharge from tb_bill where concessionairecode = \'04-1-12-069-000728\' ) b left join (Select billcode,sum(bill) + sum(penalty) as amountpaid from tb_payment where concessionairecode = \'04-1-12-069-000728\' group by billcode) as p on b.billcode=p.billcode) as z  on x.billcode = z.billcode  SET x.paid = z.paid  where concessionairecode = \'04-1-12-069-000728\'',NULL,3),(4922,'2023-05-12','Edit Payment History','UPDATE tb_payment SET paymentdate = CASE WHEN paymentid=\'189\' THEN \'2023/05/12\' ELSE paymentdate END, bill = CASE WHEN paymentid=\'189\' THEN \'662.18\' ELSE bill END, penalty = CASE WHEN paymentid=\'189\' THEN  \'0\' ELSE penalty END, totalamount = CASE WHEN paymentid=\'189\' THEN \'662.18\' ELSE totalamount END, cash = CASE WHEN paymentid=\'189\' THEN \'662.18\' ELSE cash END where paymentid = \'189\'~~>DELETE from tb_cheque where transactioncode = \'01-1-12-345E-001308-00001\'~~>UPDATE tb_bill as x left join(select b.billcode,if((b.finalbillcharge-if(isnull(p.amountpaid),0,p.amountpaid))>0,0,1) as paid from (select billcode,((billcharge + GETPENALTY(billcharge, duegraceperiod,  dueexempt,  arrears,  penaltyamount,  paid))+adjustdebit)-adjustcredit as finalbillcharge from tb_bill where concessionairecode = \'01-1-12-345E-001308\' ) b left join (Select billcode,sum(bill) + sum(penalty) as amountpaid from tb_payment where concessionairecode = \'01-1-12-345E-001308\' group by billcode) as p on b.billcode=p.billcode) as z  on x.billcode = z.billcode  SET x.paid = z.paid  where concessionairecode = \'01-1-12-345E-001308\'',NULL,3),(4923,'2023-05-12','Edit Payment History','UPDATE tb_payment SET paymentdate = CASE WHEN paymentid=