--
-- Table structure for table `tb_watermeter`
--

DROP TABLE IF EXISTS `tb_watermeter`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_watermeter` (
  `watermeterid` int(11) NOT NULL AUTO_INCREMENT,
  `watermetercode` varchar(25) DEFAULT NULL,
  `watermeterno` int(11) DEFAULT NULL,
  `concessionairecode` varchar(20) DEFAULT NULL,
  `meterno` varchar(20) DEFAULT NULL,
  `brand` varchar(20) DEFAULT NULL,
  `dateinstalled` date DEFAULT NULL,
  `initialreading` int(11) DEFAULT NULL,
  `datepullout` date DEFAULT NULL,
  `previousreading` int(11) DEFAULT NULL,
  `presentreading` int(11) DEFAULT NULL,
  `datepreviousreading` date DEFAULT NULL,
  `datepresentreading` date DEFAULT NULL,
  `meterconsumed` int(11) DEFAULT NULL,
  `month` int(2) DEFAULT NULL,
  `year` int(4) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT NULL,
  `districtno` int(11) DEFAULT NULL,
  PRIMARY KEY (`watermeterid`),
  KEY `indx_concessionairecode` (`concessionairecode`),
  KEY `indx_meterno` (`meterno`),
  KEY `indx_billingperiod` (`year`,`month`)
) ENGINE=MyISAM AUTO_INCREMENT=1430 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

